function rigReach(a,b,length,minimum=0){const dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy);if(d<.001)return rigPoint(a.x,a.y+minimum);const k=clamp(d,minimum,length)/d;return rigPoint(a.x+dx*k,a.y+dy*k);}
