  if(action==='fall'){pose.hip.y=61;pose.tilt=.07;pose.feet=[rigPoint(18,91),rigPoint(47,90)];pose.hands=[rigPoint(1,39),rigPoint(63,39)];}
  if(action==='land'){const v=1-rigEase(p);pose.hip.y+=12*v;pose.tilt=.14*v;pose.hands=[rigPoint(5,57),rigPoint(58,59)];}
  if(action==='dash'){pose.hip.y=68;pose.tilt=.45;pose.feet=[rigPoint(10,91),rigPoint(38,88)];pose.hands=[rigPoint(3,48),rigPoint(39,50)];pose.weapon=.02;}
