  if(action==='reach'){pose.hands=[rigPoint(14,56),rigPoint(64,48)];pose.tilt=.06;}
  if(action==='cast'){const lift=rigEase(p<.48?p/.48:(1-p)/.52);pose.hands=[rigPoint(17-11*lift,62-19*lift),rigPoint(46+16*lift,62-30*lift)];pose.tilt=-.08*lift;pose.weapon=lerp(-.35,-1.2,lift);}
