    for(const key of ['feet','hands','shoulders','hips'])for(let i=0;i<2;i++)for(const axis of ['x','y'])p[key][i][axis]=lerp(p[key][i][axis],rest[key][i][axis],u);
    p.tilt=lerp(p.tilt,0,u);p.headTilt=lerp(p.headTilt,rest.headTilt,u);
