  if(id==='dagger'){storyPoly(g,'#e2f4e9',[[-3,-13],[3,-10],[2,7],[-2,7]]);storyRect(g,'#cfad6c',-6,6,12,3);storyRect(g,'#795740',-2,9,4,8);storyRect(g,'#83d6d5',-1,-7,1,11);}
