  storyPoly(g,'#293438',[[0,9],[7,1],[23,1],[28,7],[31,18],[6,20],[-2,15]]);storyPoly(g,'#b9b7a1',[[3,9],[9,4],[22,4],[26,9],[25,16],[6,17]]);
