    stageActor(frame,'hero',{x:145,motion:v==='unlock'?'reach':'idle',mood:'calm'});
    for(let i=0;i<4;i++)stageActor(frame,['aster','mira','rook','fern'][i],{x:273+i*83,motion:i===index?({greet:'wave',laugh:'laugh',salute:'salute',lock:'cast',boast:'cheer',pledge:'reach',unlock:'guard'}[v]||'idle'):'idle',face:i===index?-1:1,mood:i===index?'smile':'calm'});
    if(v==='lock')frame.effects.push('lockSpark');
