  const mira=stageActor(f,'mira',{motion:'cast',phase:duelProgress(t,.15,.15+(.37-.15)/.48),face:-1});
  if(t>=.48){
    rook.motion=mira.motion='hurt';rook.phase=mira.phase=1;
    rook.fromMotion='attack';rook.fromPhase=.52;rook.blend=storyWindow(t,.48,.57);mira.fromMotion='cast';mira.fromPhase=.72;mira.blend=rook.blend;
    rook.x=lerp(166,FALLEN_PARTY_X[2],fall);mira.x=lerp(224,FALLEN_PARTY_X[1],fall);
    rook.rotation=mira.rotation=-Math.PI/2*fall;
    rook.armed=mira.armed=fall<.3;
  }
  const fernFall=rigEase(duelProgress(t,.76,.92));
  stageActor(f,'fern',{x:lerp(56,FALLEN_PARTY_X[3],fernFall),motion:fernFall?'hurt':'cast',
    phase:fernFall?1:clamp(duelProgress(t,.32,.85),0,.6),rotation:-Math.PI/2*fernFall,armed:!fernFall,mood:'shock',fromMotion:'cast',fromPhase:.58,blend:fernFall?storyWindow(t,.76,.87):1});
