  stageActor(f,'hero',{x:380-rigEase(duelProgress(t,.42,.57))*12+rigEase(duelProgress(t,.72,.95))*12,
    motion:t>.42&&t<.57?'run':'guard',phase:duelProgress(t,.42,.57),armed:true,fromMotion:t<.57?'guard':'run',fromPhase:t<.57?0:1,blend:t>.42&&t<.57?storyWindow(t,.42,.48):t>=.57?storyWindow(t,.57,.65):1});
