    const start=rigSocket({...mira,motion:'cast',phase:.48}),x=lerp(start.x,167,d.bolt),y=lerp(start.y,212,d.bolt);
    storyLine(g,'#7150bd',6,[[start.x,start.y],[x,y]]);storyLine(g,'#ecdcff',2,[[start.x,start.y],[x,y]]);
