    if(p.id==='snack'){storyPoly(g,'#bc8152',[[-8,-5],[3,-8],[10,-3],[8,5],[-6,6],[-10,1]]);storyLine(g,'#eed09a',2,[[-5,-4],[-2,2],[1,-5],[4,2]]);}
    g.restore();
