function advancePlotScene(){
  const p=plotState();if(p.scene==='cell'||!p.scene)return;
  const scene=QUESTIONS.story.scenes[p.scene];if(p.scenePage<scene.pages.length-1){p.scenePage++;markStoryChanged();renderPlotScene();return;}
  const id=p.scene;p.scene=null;p.scenePage=0;stopStoryAnimation();AudioEngine.setDialogue(false);hide(plotUI.overlay);markStoryChanged();
  finishPlotScene(id);
}
function finishPlotScene(id){
  const p=plotState();
  switch(id){
    case 'origin':p.originSeen=true;showWorldIntro();break;
    case 'prisoners':p.prisonersMet=true;openAssessment();break;
    case 'rescue':p.partyFreed=true;grantWeapon('byte_dagger',{source:'ROOK'});player.health=MAX_HEALTH;resetParty();break;
    case 'camp1':case 'camp2':case 'camp3':p.camps[Number(id.slice(-1))-1]=true;break;
    case 'betrayal':p.betrayed=true;showPlotScene('cell');break;
    case 'escape':p.escaped=true;player.health=MAX_HEALTH;setCheckpoint(205,'Prison escape');resetPlayer(true,3);break;
    case 'rivals':p.rivalsSeen=true;p.finalPhase='paladin';startFinalBattle();break;
    case 'paladinFall':p.finalPhase='barrier';openAssessment();break;
    case 'barrier':p.finalPhase='demon';startFinalBattle();break;
    case 'fusion':p.fusionSeen=true;p.finalPhase='fused';startFinalBattle();break;
    case 'ending':p.immortal=true;p.finalPhase='complete';finishGame();break;
  }
  markStoryChanged();updateHud();canvas.focus?.();
}
function startFinalBattle(){
  setCheckpoint(TERMINAL_COL+4,'Throne arena');resetPlayer(true,3);spawnBoss();
  player.x=(TERMINAL_COL+4)*TILE;state.needsRender=true;
}
function renderPrison(){
  const p=plotState();plotUI.title.textContent='The cell beneath Oathforge';plotUI.speaker.textContent='A locked door is still a problem';plotUI.page.textContent='Explore • forge • escape';plotUI.next.hidden=true;
  let text='BYTE lingered in the corridor, looking for a response you refused to give him. He nudged a fallen parchment with his shoe. A broken seal caught the torchlight: Veyr’s treasury. “So that was their price.” He kicked it under the door. “Four claims to one crown. They sold you cheaply.” The scroll stopped beside your knees. He backed away, then lifted from the floor as though the world owed him that convenience. “I am getting a snack. If you are breathing when I return, do it quietly.” You listened until the corridor was empty. Then you reached for the paper.';
  if(p.scrollRead)text='The scroll described a route: the catacombs beneath Oathforge, a chain of watch posts across the ravine, and the treasury beneath Veyr’s hall. Four different hands had written claims in the margin. You recognised Aster’s precise letters. Beside the old bones, someone had scratched another message: “Heat. Shape. Cool.” The cell had once been a smith’s punishment room. A hearth, an anvil, a water trough. A previous prisoner had left a way to think, if not a way out.';
  if(p.daggerFound)text='Boot pocket. Nobody checks boots. You eased out Rook’s little dagger and slipped its point beneath the corroded rivet holding your cuffs. A careful lever; a second try. The rivet gave before the blade did. You rubbed your wrists, then carried the dagger to the hearth. The door lock needed three teeth the blade did not yet have. “Axe for the big problems,” you whispered. “All right. This one is yours.”';
  if(p.forgeStep>0)text=['','You held the dagger’s edge over the old coals. Orange crept along the steel. You watched until it glowed evenly, then drew it out. The lock’s pattern had three notches; the anvil would keep the blade steady while you shaped them.','One careful blow for each notch. You checked the pattern between strokes instead of hitting harder. Three uneven teeth, but the spacing matched. The metal still needed cooling before it could bear the turn of the lock.'][p.forgeStep]||text;
  if(p.keyForged)text='The hot edge hissed in the trough. When the steam cleared, you lifted a key that still had Rook’s dagger grip. You ran a thumb beside the new teeth and thought of the nameless prisoner who had scratched instructions on the wall. “Thank you,” you told the bones. Then you went to the door.';
  plotUI.text.textContent=text;plotUI.hint.textContent='Your pack will be recovered after escape. This puzzle never removes your Python work or completed shrines.';
  scenePageData={speaker:p.scrollRead?'Narrator':'BYTE',mood:'grin',hideByte:p.scrollRead,byteExit:!p.scrollRead,beat:p.daggerFound?'forge':p.scrollRead?'scroll':undefined,forgeStep:p.forgeStep,forgeAction:p.daggerFound?['inspect','heat','hammer','quench'][p.forgeStep]:undefined,art:'prison'};renderStoryPortrait(scenePageData);AudioEngine.setDialogue(!p.scrollRead);animateStoryPicture('prison');
  if(!p.scrollRead)storyChoice('Read the discarded scroll',()=>{p.scrollRead=true;markStoryChanged();renderPlotScene();});
  else if(!p.daggerFound)storyChoice('Inspect your hidden dagger',()=>{p.daggerFound=true;grantWeapon('byte_dagger',{equip:false,announce:false});markStoryChanged();renderPlotScene();});
  else if(!p.keyForged){
    ['Heat the blade','Hammer the notches','Quench in water'].forEach((label,index)=>storyChoice(label,()=>forgePrisonKey(index)));
  }else storyChoice('Turn the key and leave the cell →',()=>showPlotScene('escape'));
}
function forgePrisonKey(step){
  const p=plotState();if(p.scene!=='cell'||!p.scrollRead||!p.daggerFound||p.keyForged)return false;
  if(step!==p.forgeStep){plotUI.hint.textContent='That would not hold its shape yet. Follow the note: Heat → Shape → Cool. Your work is still here.';return false;}
  p.forgeStep++;sfx.equip();
  if(p.forgeStep===3){p.keyForged=true;state.weapons=state.weapons.filter(id=>id!=='byte_dagger');normalizeWeaponState();}
  markStoryChanged();renderPlotScene();return true;
}
